-- M-Core booking payment flow, step 3 of 4: staff alerts (Supabase Cron, plain SQL). They land in the bell and, through the existing
-- notifications -> push-send webhook, as phone push. No edge function change, no deploy.
-- WRITE-ONLY: run in Supabase SQL Editor AFTER booking_pay_01.sql and booking_pay_02.sql. Rerun-safe. No functions, no dollar quoting.
--   mcore-bkpay-notify  (every minute): new booking receipt -> owners / admins ("to review", claimed once through notified_at);
--                       receipt still pending after pay_settings.bk_remind_min (default 30, 0 = off) -> one reminder (reminded_at).
--   mcore-bkpay-morning (01:00 UTC = 9:00 AM MYT daily): per tenant, waiting / verified yesterday / rejected yesterday. Skipped when all are 0.
create extension if not exists pg_cron;
select cron.unschedule(jobid) from cron.job where jobname in ('mcore-bkpay-notify', 'mcore-bkpay-morning');
select cron.schedule(
  'mcore-bkpay-notify',
  '* * * * *',
  'with c as (update public.payment_claims pc set notified_at = now() where pc.status = ''pending'' and pc.notified_at is null and pc.deleted_at is null and exists (select 1 from public.bookings b where b.tenant_id = pc.tenant_id and b.invoice_id = pc.invoice_id) returning pc.id, pc.tenant_id, pc.invoice_id, pc.amount) insert into public.notifications (tenant_id, user_id, title, body, category, kind, type, priority, link, ref_table, ref_id) select c.tenant_id, u.id, case when u.language = ''bm'' then ''Resit bayaran tempahan untuk disemak'' else ''Booking payment receipt to review'' end, case when u.language = ''bm'' then concat_ws('' · '', bk.quote_ref, i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Sahkan atau tolak dalam Bayaran untuk disemak.'' else concat_ws('' · '', bk.quote_ref, i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Verify or reject in Payments to review.'' end, ''sales'', ''action'', ''sales.booking_receipt'', 2, jsonb_build_object(''page'', ''sales'', ''params'', jsonb_build_object(''bkpq'', 1)), ''payment_claims'', c.id::text from c join public.invoices i on i.id = c.invoice_id and i.tenant_id = c.tenant_id left join lateral (select b.quote_ref from public.bookings b where b.tenant_id = c.tenant_id and b.invoice_id = c.invoice_id limit 1) bk on true join public.user_profiles u on u.tenant_id = c.tenant_id and lower(coalesce(u.role, '''')) in (''owner'', ''admin'') and coalesce(u.is_active, true); with c as (update public.payment_claims pc set reminded_at = now() where pc.status = ''pending'' and pc.reminded_at is null and pc.deleted_at is null and exists (select 1 from public.bookings b where b.tenant_id = pc.tenant_id and b.invoice_id = pc.invoice_id) and coalesce((select ps.bk_remind_min from public.pay_settings ps where ps.tenant_id = pc.tenant_id), 30) > 0 and pc.created_at < now() - make_interval(mins => coalesce((select ps.bk_remind_min from public.pay_settings ps where ps.tenant_id = pc.tenant_id), 30)) returning pc.id, pc.tenant_id, pc.invoice_id, pc.amount, pc.created_at) insert into public.notifications (tenant_id, user_id, title, body, category, kind, type, priority, link, ref_table, ref_id) select c.tenant_id, u.id, case when u.language = ''bm'' then ''Resit tempahan masih menunggu semakan'' else ''Booking receipt still waiting for review'' end, case when u.language = ''bm'' then concat_ws('' · '', i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Dihantar '' || to_char(c.created_at at time zone ''Asia/Kuala_Lumpur'', ''HH12:MI AM'') || '' (MYT). Slot pelanggan ditahan sehingga anda semak.'' else concat_ws('' · '', i.ref_no, ''RM '' || to_char(c.amount, ''FM999,999,990.00'')) || ''. Sent '' || to_char(c.created_at at time zone ''Asia/Kuala_Lumpur'', ''HH12:MI AM'') || '' (MYT). The customer''''s slot is held until you review.'' end, ''sales'', ''action'', ''sales.booking_receipt_remind'', 2, jsonb_build_object(''page'', ''sales'', ''params'', jsonb_build_object(''bkpq'', 1)), ''payment_claims'', c.id::text from c join public.invoices i on i.id = c.invoice_id and i.tenant_id = c.tenant_id join public.user_profiles u on u.tenant_id = c.tenant_id and lower(coalesce(u.role, '''')) in (''owner'', ''admin'') and coalesce(u.is_active, true);'
);
select cron.schedule(
  'mcore-bkpay-morning',
  '0 1 * * *',
  'with y as (select ((now() at time zone ''Asia/Kuala_Lumpur'')::date - 1) d), t as (select pc.tenant_id, count(*) filter (where pc.status = ''pending'') np, coalesce(sum(pc.amount) filter (where pc.status = ''pending''), 0) ap, count(*) filter (where pc.status = ''approved'' and (pc.reviewed_at at time zone ''Asia/Kuala_Lumpur'')::date = (select d from y)) nv, coalesce(sum(coalesce(p.amount, pc.amount)) filter (where pc.status = ''approved'' and (pc.reviewed_at at time zone ''Asia/Kuala_Lumpur'')::date = (select d from y)), 0) av, count(*) filter (where pc.status = ''rejected'' and (pc.reviewed_at at time zone ''Asia/Kuala_Lumpur'')::date = (select d from y)) nr from public.payment_claims pc left join public.payments p on p.id = pc.payment_id and p.tenant_id = pc.tenant_id where pc.deleted_at is null and (pc.status = ''pending'' or pc.reviewed_at > now() - interval ''3 days'') and exists (select 1 from public.bookings b where b.tenant_id = pc.tenant_id and b.invoice_id = pc.invoice_id) group by pc.tenant_id) insert into public.notifications (tenant_id, user_id, title, body, category, kind, type, priority, link) select t.tenant_id, u.id, case when u.language = ''bm'' then ''Bayaran tempahan: ringkasan pagi'' else ''Booking payments: morning summary'' end, case when u.language = ''bm'' then t.np || '' menunggu semakan (RM '' || to_char(t.ap, ''FM999,999,990.00'') || '') · '' || t.nv || '' disahkan semalam (RM '' || to_char(t.av, ''FM999,999,990.00'') || '') · '' || t.nr || '' ditolak semalam'' else t.np || '' waiting for review (RM '' || to_char(t.ap, ''FM999,999,990.00'') || '') · '' || t.nv || '' verified yesterday (RM '' || to_char(t.av, ''FM999,999,990.00'') || '') · '' || t.nr || '' rejected yesterday'' end, ''sales'', ''for_you'', ''sales.booking_pay_digest'', case when t.np > 0 then 1 else 0 end, jsonb_build_object(''page'', ''sales'', ''params'', jsonb_build_object(''bkpq'', 1)) from t join public.user_profiles u on u.tenant_id = t.tenant_id and lower(coalesce(u.role, '''')) in (''owner'', ''admin'') and coalesce(u.is_active, true) where t.np + t.nv + t.nr > 0;'
);
-- check (read-only)
select jobid, jobname, schedule, active from cron.job where jobname like 'mcore-bkpay-%' order by jobname;
